# Mobile pages helper
def mobile_page(filename,title,body,desc):
    html=f'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><link rel="stylesheet" href="../styles.css"></head><body class="mobile-demo"><div class="phone"><div class="phone-top"><b>RecruitFlow</b><span>●</span></div>{body}<div class="mobile-nav"><span>◆<small>Home</small></span><span>✓<small>Tasks</small></span><span>◉<small>Talent</small></span><span>☰<small>More</small></span></div></div></body></html>'''
    (PAGES/filename).write_text(html,encoding='utf-8')
    screens.append((filename,title,'Mobile',desc))

